SELECT COUNT(*)
FROM tb_assessment_answer a
JOIN tb_assessment_question q ON a.question_id = q.id
WHERE q.assessment_time_id = #{assessmentTimeId}
  AND a.user_id = #{userId}

SELECT q.assessment_time_id AS assessmentTimeId, COUNT(*) AS count FROM tb_assessment_answer a JOIN tb_assessment_question q ON a.question_id = q.id WHERE q.assessment_time_id IN
#{id}
AND a.user_id = #{userId} GROUP BY q.assessment_time_id

